def _shared_domain_keys(domain: str) -> tuple[str, ...]:
    canonical = NON_JA_PANEL_FALLBACK_TRANSLATIONS["es"][domain]
    return tuple(
        key
        for key in canonical
        if all(key in domains.get(domain, {}) for domains in NON_JA_PANEL_FALLBACK_TRANSLATIONS.values())
    )

_AI_EFFECT_PANEL_EXTRA_KEYS = _shared_domain_keys("EffectPanel")
